// Proactive Business English B2 · Syria Edition · Book 2 · Unit 17 — Answer Key (separate book)
const L = require('./lib');
const { p, h1, h2, h3, pb, sp, stage, box, dlg, table, C } = L;
const out = [];
const sample = (title, paras) => box(title, paras, 'FFFFFF', C.navy);
const note = t => p(`_${t}_`, { color: '595959' });

out.push(h1('Answer Key · Unit 17  Summarising at Length'));
out.push(p('_Proactive Business English · B2 · Book 2 · Syria Edition_', { color: '7F7F7F' }));
out.push(box('How to use this key', [
  'Every task has an answer. Where the task is open, the key gives a **full sample answer**. Samples show one good B2 answer – learners\' own answers will be different and that is correct.',
  '⚠ **Unit 17 is the only unit in the level whose whole task is subtraction.** **Two hundred and fourteen pages, twenty-two documents, and two pages at the end of it** — ⚠ **and the hardest sentence in the unit is the one that says what the bundle does not contain.**',
  '⚠ **The six things taught, and 17.5 is the one that cannot be done alone.** ⚠ **The reader without the original (17.1) · proportion (17.2) · quoting fairly (17.3) · the absence (17.4) · the bundle-shut reading (17.5) · the neutral summary (17.6).** ⚠ **17.5 requires a second person**, **because the four sentences that fail look right to the writer, who knows what the referred-to documents say.**',
  '⚠ **The distinction to drill in 17.1 is index against summary.** ⚠ **An index is organised by document and a summary by question, and nobody decides anything by document** — **so twenty-two paragraphs about twenty-two documents has done the work and not the job.** ⚠ **And the test is not accuracy but *would a decision taken on this alone be the same decision*.**',
  '⚠ **17.2 separates two words everybody conflates.** ⚠ **Relevance is what gets a document into a bundle; consequence is what earns it a paragraph** — **and *correct, relevant and of no consequence* is the usual condition of a document in any long file.**',
  '⚠ **17.7 is the quietest mediation in the book and the most alarming.** ⚠ **Mr Attar does not recognise a sentence the firm has been quoting for two years, because it is the first half of one** — **and the half left off is the half the arbitration turns on.** **He will not write a letter explaining it, and his reason is the one a layman never sees: it would make him a witness in a dispute about a company he audits.** ⚠ **The remedy is that one person reads page four.**',
  '⚠ **Word counts.** Stage 6 asks for **80 words or more** and stage 7 for **200 to 240**. ⚠ **Cycle 7\'s exam task is Writing Part 1, an internal communication, 40 to 50 words, 10 marks**; **the exam practice is Reading Part 2, sentence insertion, the third time in the level.**',
], C.grey, C.navy));

// ===================== 17.1 =====================
out.push(h2('17.1  The reader who will not read the original'));
out.push(stage('1', 'Get ready'));
out.push(p('**a**  Open. ⚠ **Expect the two answers to be different people, and expect nobody to have read all of the longest document** — **which is the condition the unit is written for.**'));
out.push(p('**b**  ⚠ **The second.** ⚠ **The first is an index: twenty-two paragraphs about twenty-two documents, organised by the file rather than by the decision.**'));
out.push(stage('2', 'Listen and read'));
out.push(p('**a**  B   **b**  1 ⚠ **Mr Sayegh reads the bundle because he is paid to; the arbitrator reads the parts she is taken to; Mr Ayoub reads two pages; the bank would read half a page; and in five years somebody reads the summary with the bundle in a box.**  2 ⚠ **Being read by somebody with no access to the original at all.**'));
out.push(p('⚠ **The index-against-summary distinction is the lesson and it should be put as a rule:** ⚠ **an index is organised by document, a summary by question, and nobody decides anything by document.** **The two are indistinguishable in a contents list, which is why the fault survives.**'));
out.push(p('⚠ **Name the readers and what each will read**, **and notice which one nobody writes for:** ⚠ **the reader in five years, with the bundle in a box.** **That is the reader this whole book has been building towards and Unit 18 is about them.**'));
out.push(p('⚠ **The test is the one to repeat.** ⚠ **Not *is it accurate* — which a writer always answers yes to — but *would a decision taken on this alone be the same decision*.** **A writer can actually answer the second.**'));
out.push(p('⚠ **And *accurate and unusable is worse than inaccurate* is the sentence to put on the board.** ⚠ **An inaccurate summary gets corrected; an unusable one gets ignored, and nobody tells the writer** — **so the fault repeats for a career.**'));
out.push(p('**Language box – Practise (sample):**  _**The document: the 2024 audit file, 96 pages.**_ ⚠ _**Readers:** Mr Attar (all of it, paid to) · Mr Ayoub (the three-page letter) · Nadia (the schedules) · and whoever has this job in 2032 (the three-page letter, with the file in a box)._ ⚠ _**The length that is a decision:** three pages, because that is what Mr Ayoub reads and what will survive._'));
out.push(stage('3', 'Practise – sample with role card 1'));
out.push(dlg(null, [
  ['A', 'Twenty-two paragraphs, one for each document.'],
  ['B', 'What question does it answer?'],
  ['A', 'All of them.'],
  ['B', 'Name one and show me where the answer is.'],
  ['A', 'Was the condition known to us? …It is in paragraph nine and partly in paragraph fourteen.'],
  ['B', 'So a reader with that question has to read twenty-two paragraphs to find two.'],
  ['A', 'They could use the headings.'],
  ['B', 'The headings are document numbers.'],
  ['A', 'Then it is organised by the file and not by the decision.'],
  ['B', 'Which is an index, and an index is useful. It is not what anybody asked you for.']
]));
out.push(note('"An index is useful. It is not what anybody asked you for" is the line to end on, because the work in a twenty-two-paragraph summary is real and should not be dismissed. The quickest way to show the fault is the one B uses: ask for a question and make A find the answer in their own document. When the answer turns out to be in two non-adjacent paragraphs, the diagnosis makes itself. Keep the index — it is the working document the summary is built from — and then write the summary.'));
out.push(stage('3R', 'Perform'));
out.push(p('**Listener task:** ⚠ **An index is organised by document and a summary by question.** ⚠ **The four readers, and the one that matters most is the one in five years** — **because they are the only reader who cannot ask the writer anything.**'));
out.push(stage('4', 'Your turn – sample table'));
out.push(table(['The reader', 'What they will read', 'Do they have the original?', 'What they will do with it'], [
  ['**Mr Attar**', '**all 96 pages**', '⚠ **yes** — **he wrote most of it**', '**sign the accounts**'],
  ['**Mr Ayoub**', '**the three-page letter**', '**in the next room**', '**decide whether to provide for Homs**'],
  ['**Nadia**', '**the schedules only**', '**yes**', '**reconcile them**'],
  ['⚠ **whoever has my job in 2032**', '⚠ **the three-page letter**', '⚠ **no — the file will be in a box**', '⚠ **answer a question nobody has asked yet**'],
], [1.8, 2.2, 1.8, 2.6]));
out.push(stage('4R', 'Report – sample'));
out.push(p('_**The document is ninety-six pages. Mr Attar will read all of it. Mr Ayoub will read three pages. In five years somebody will read the three pages with the file in a box. So the summary is three pages, and that is a decision because it is what the two readers who decide anything will actually read.**_'));
out.push(p('⚠ **Two counts.** **How many documents had a reader who read all of them: about half, and in those cases it was somebody paid by the hour.** ⚠ **And how many had a five-year reader named? None** — **which is the gap the whole of Unit 18 is about, and it is worth saying so here.**'));
out.push(stage('5', 'Read'));
out.push(p('**1**  ⚠ **By question** — *what is claimed · was it known · was it disclosed · what does the agreement require*. ⚠ **Three of the twenty-two decide it; nineteen are correct, relevant and of no consequence.**'));
out.push(p('**2**  ⚠ **The root-cause paper of March, at page 61.** ⚠ **It is Sham Trading\'s own document and it establishes the date the condition was identified** — **which is the claim against the firm, found in the firm\'s own file.**'));
out.push(p('**3**  ⚠ **Because a reader told that nineteen documents do not matter has been asked to take a very large statement on trust.** ⚠ **Nineteen lines with nineteen page numbers cost half a page and convert it into something anybody can check in a morning** — **and if the writer is wrong about one, the list is what lets somebody say so.**'));
out.push(stage('6', 'Write with help – sample (184 words)'));
out.push(sample(null, [
  '**THE 2024 AUDIT FILE: SUMMARY. 20 January. L. Barakat. Three pages. Page 1.**',
  '⚠ **This summary is written to be acted on without the file.** **The file is 96 pages and 31 schedules; every load-bearing sentence below carries a page reference.** ⚠ **Four schedules decide the open questions. Twenty-seven are correct, relevant and of no consequence.**',
  '**The question** | **The answer, and where**',
  '**Is there an unprovided liability?** | **One: the Homs site, carried at 2.4 million on an internal estimate of 2021 and never valued. [p. 18]**',
  '⚠ **What does the auditor require before signing?** | ⚠ **A valuation by a third party, or a provision. He has required this in each of the last three years and it is in the same words each time. [p. 18, and 2022 p. 14, 2023 p. 16]**',
  '**What is the stock position?** | **Counted on 28 December; the count ties to the ledger within 0.4 per cent. [pp. 40–44]**',
  '⚠ **What does the file say about the gate sheet?** | ⚠ **That it is the primary record of what left the yard, and is not a record of condition. [p. 4]** — **and the second half of that sentence is quoted nowhere in our own correspondence**',
  '⚠ **What is not in the file at all.** **There is no valuation of the Homs site of any date.** ⚠ **The absence is ours: it has been asked for three times and never obtained.**',
  '⚠ **The twenty-seven of no consequence** are listed on page 3 with a line each, **because a reader told that twenty-seven schedules do not matter will want to see that somebody read them.**',
]));
out.push(stage('6P', 'Check together – sample completed checklist'));
out.push(table(['Checklist', '✓ / ✗'], [
  ['A first line saying it stands alone, with the size of the original', '**✓** — **96 pages, 31 schedules, 4 and 27**'],
  ['Organised by question, not by document', '**✓**'],
  ['A page reference inside every load-bearing answer', '**✓** — **and three years of references on the second**'],
  ['The document against you named, and said to be yours', '**✓** — **the absence has been asked for three times**'],
  ['The irrelevant majority listed with one line each', '**✓**'],
], [5, 1]));
out.push(note('The fourth row of that sample is doing something the unit has not taught yet and it is worth pointing at: the auditor has required the same thing in the same words for three years, and the summary gives all three references. A requirement repeated identically three times is a different fact from a requirement made once, and the only way a reader sees it is if the summary carries the three page numbers. That is 18.3 arriving early — a document that lets a stranger trace a pattern rather than an event.'));
out.push(stage('6R', 'Share'));
out.push(p('⚠ **Read the question columns aloud and ask whether a reader could act on any ONE question without the others.** ⚠ **If they could not, the summary is still organised by document with questions written over the top** — **which is the commonest half-finished version of this task.**'));
out.push(stage('7', 'Write freely – sample (223 words)'));
out.push(sample(null, [
  'The longest document my work produced last year is the tender for the hospital benches, which ran to forty-one pages with the schedules.',
  'I wrote it. Nobody read all of it, including me, because I assembled four of the schedules from last year\'s and did not reread them.',
  'Who acted on it was the hospital\'s purchasing officer, and I know what she read because she telephoned about it. She read page one, the price schedule, and the delivery clause. Three pages of forty-one, and she asked two questions, both about the delivery clause.',
  'A two-page version would have said: what we are offering, the price, the delivery terms, what we are not offering, and the two things in the schedules that differ from last year.',
  'The last of those is the one nobody would have thought to put in and it is the one that mattered. One of the four schedules I copied forward had a lead time in it that we can no longer meet, and she did not notice and neither did I, and it is now in a contract.',
  'The five-year reader is whoever administers that contract. They will have the forty-one pages and no idea which parts were copied forward and which were written for this tender.',
  'That is the thing a summary of my own tender should have said, and I would not have known to say it until this cycle.',
]));
out.push(p('⚠ **The fifth paragraph is the finding and it is the best argument in the unit for summarising your own documents.** ⚠ **A lead time copied forward from last year\'s tender is now in a contract, and nobody noticed because nobody read the schedules** — **including the writer.** ⚠ **A summary that said *the two things in the schedules that differ from last year* would have caught it**, **and the task of writing it would have required somebody to look.**'));
out.push(stage('7P', 'Respond'));
out.push(p('⚠ **The slip asks whether the same decision would be taken on the summary alone.** ⚠ **It is the test from the Language box applied to somebody else\'s work**, **and a reviewer can answer it where the writer cannot.**'));
out.push(stage('7R', 'Share'));
out.push(p('⚠ **Expect one of three to have had a complete reader, and expect it to be somebody paid by the hour.** ⚠ **The finding: the only complete reader of a long document is usually the one being paid to read it** — **and everybody else is reading a summary, whether one has been written or not.**'));

// ===================== 17.2 =====================
out.push(pb());
out.push(h2('17.2  What gets a line and what gets a page'));
out.push(stage('1', 'Get ready'));
out.push(p('**a**  Open. ⚠ **Every learner has one, and the part that mattered is usually not the part that got the most space** — **which is the diagnosis the cycle starts from.**'));
out.push(p('**b**  ⚠ **The second.** ⚠ **A ratio of three paragraphs to nineteen lines tells a reader the shape of the file; twenty-two equal paragraphs tells them nothing at all.**'));
out.push(stage('2', 'Listen and read'));
out.push(p('**a**  B   **b**  1 ⚠ *If this document did not exist, would the answer change?* — **yes is a paragraph, no is a line.**  2 ⚠ **Because a reader told that nineteen documents do not matter wants to see that somebody read them** — **and nineteen lines cost half a page.**'));
out.push(p('⚠ **The test is the whole cycle and its virtue is that it needs no judgement about importance.** ⚠ **Would the answer change?** **A clerk can apply it** — **where *is this important* can be argued about for an hour by people who agree about everything else.**'));
out.push(p('⚠ **Relevance and consequence are the two words to separate.** ⚠ **Relevance gets a document into a bundle; consequence earns it a paragraph** — **and *correct, relevant and of no consequence* is the commonest condition of a document in a long file, which nobody tells learners.**'));
out.push(p('⚠ **The ratio is the finding, and that is a claim worth defending.** ⚠ **Three to nineteen tells a reader the shape of the case before a word of it** — **and it is the only part of a summary that communicates before being read.**'));
out.push(p('⚠ **And the argument for listing the irrelevant ones is about correction, not completeness.** ⚠ **A document left out is one you have decided about in private; a one-line entry with a page number is a decision anybody can correct in a morning** — **and the writer is wrong about one of nineteen often enough for this to matter.**'));
out.push(p('**Language box – Practise (sample, three of thirty-one):**  _**Schedule 4, Homs carrying value:** ⚠ **if it did not exist the answer would change** — **paragraph.** **Schedule 11, the stock count:** ⚠ **if it did not exist the answer would change** — **paragraph.** **Schedule 19, petty cash:** ⚠ **no** — **line, and it is correct and relevant and of no consequence.**_'));
out.push(stage('3', 'Practise – sample with role card 1'));
out.push(dlg(null, [
  ['A', 'Schedule 19 should have a paragraph. The petty cash reconciliation is relevant.'],
  ['B', 'If schedule 19 did not exist, would the answer change?'],
  ['A', 'The answer to what?'],
  ['B', 'To any of the four questions your summary is organised around.'],
  ['A', '…No.'],
  ['B', 'Is it relevant?'],
  ['A', 'Yes. It is part of the audit.'],
  ['B', 'So it is relevant and of no consequence.'],
  ['A', 'Which is not a thing I had a word for.'],
  ['B', 'It is the commonest condition of a document in any file, and it gets a line.'],
]));
out.push(note('"Which is not a thing I had a word for" is the honest response and it is why this cycle works. Most learners have only one category — relevant or not — and the middle category is where most of a file lives. Once they have the word, the test becomes mechanical and the arguments stop. It is also worth saying that the middle category is not a criticism of the document: a petty cash reconciliation is exactly as correct and as necessary as the schedule that decides the question, and it gets a line because of what it decides and not because of what it is worth.'));
out.push(stage('3R', 'Perform'));
out.push(p('**Listener task:** ⚠ **The test in one sentence.** ⚠ **Relevance gets it into the bundle, consequence earns it a paragraph.** ⚠ **And three to nineteen tells a reader the shape of the case before they read a word.**'));
out.push(stage('4', 'Your turn – sample table'));
out.push(table(['The part', 'If it did not exist, would the answer change?', 'Paragraph or line?', 'Relevant?'], [
  ['**schedule 4, Homs carrying value**', '⚠ **yes** — **it is the open question**', '**paragraph**', '**yes**'],
  ['**schedule 11, the stock count**', '⚠ **yes** — **the 0.4 per cent is the answer**', '**paragraph**', '**yes**'],
  ['**schedule 19, petty cash**', '⚠ **no**', '**line**', '⚠ **yes** — **and of no consequence**'],
  ['**schedule 23, fixed asset additions**', '⚠ **no**', '**line**', '**yes**'],
], [2, 3.2, 1.6, 1.4]));
out.push(stage('4R', 'Report – sample'));
out.push(p('_**The file has thirty-one schedules. Four could change the answer and get a paragraph. Twenty-seven are relevant and of no consequence and get a line. The ratio is four to twenty-seven, and it tells a reader that this audit turned on four things.**_'));
out.push(p('⚠ **Collect both counts.** **How many had given equal space before applying the test: nearly all.** ⚠ **And the ratios** — **expect one to six or worse, and say that it is normal, because a learner who finds a ratio of four to twenty-seven in their own file will assume they have done something wrong.**'));
out.push(stage('5', 'Read'));
out.push(p('**1**  ⚠ *If this document did not exist, would the answer change?* ⚠ **Three yes, nineteen no** — **and the two numbers add to twenty-two, which is how a reader knows nothing was quietly dropped.**'));
out.push(p('**2**  ⚠ **Not because they matter.** ⚠ **Document 17, the 58,000 credit note, is the one a reader will mis-read as a part payment of a 2.1 million claim.** ⚠ **Document 9 is the only pre-agreement document in the bundle, which makes it LOOK decisive** — **and it is about another consignment.** **Both get a second sentence because of how they will be read, not because of what they decide.**'));
out.push(p('**3**  ⚠ *If I am wrong about one of them, this is the page that lets somebody tell me.* ⚠ **A document left out entirely has been judged in private** — **and a summary that cannot be corrected is one nobody can rely on.**'));
out.push(stage('6', 'Write with help – sample (176 words)'));
out.push(sample(null, [
  '**SUMMARY, PAGE 3: THE TWENTY-SEVEN, AND WHY. 20 January. L. Barakat.**',
  '⚠ **The test applied to all thirty-one: if this schedule did not exist, would the answer change?** **Four yes. Twenty-seven no.**',
  '**19** | **petty cash reconciliation** | **reconciles to 240; nothing turns on it. [p. 61]**',
  '**23** | **fixed asset additions** | **two items, both the van; not in issue. [p. 70]**',
  '⚠ **26** | **the 2021 Homs closure correspondence** | ⚠ **four letters, all internal, and none of them gives a reason for the closure. [pp. 74–78]** — **see page 1, the absence**',
  '⚠ **29** | **the prior-year comparatives** | ⚠ **restated on one basis in 2023 and the restatement is explained at page 81; a reader who compares the 2022 figures to the 2024 ones without reading page 81 will find a discrepancy that is not there. [p. 81]**',
  '**31** | **the engagement letter** | **unchanged since 2019. [p. 96]**',
  '⚠ **Twenty-two more are listed on the attached sheet in the same form.** **Every one has a page number.**',
  '⚠ **Two of the twenty-seven are worth a second sentence and it is not because they matter.** ⚠ **Schedule 29, because a reader comparing years without page 81 will find a discrepancy that does not exist.** ⚠ **And schedule 26, because four letters about the Homs closure containing no reason for it is a fact somebody will want, and it belongs on page 1 as an absence rather than here as a line.**',
  '⚠ **Why this page exists.** **Twenty-seven lines cost half a page.** ⚠ **If I am wrong about one of them, this is the page that lets somebody tell me.**',
]));
out.push(stage('6P', 'Check together – sample completed checklist'));
out.push(table(['Checklist', '✓ / ✗'], [
  ['The test stated, with two counts that add to the total', '**✓** — **4 + 27 = 31**'],
  ['Each line saying what the item establishes, not what it is about', '**✓**'],
  ['A page number on every entry', '**✓**'],
  ['A second sentence for the item a reader will mis-read', '**✓** — **schedule 29**'],
  ['A paragraph saying why the page exists', '**✓**'],
], [5, 1]));
out.push(note('Schedule 26 in that sample does something the cycle does not teach: a document is identified as being of no consequence and then promoted to page 1 as an absence. Four internal letters about the Homs closure that contain no reason for it decide nothing — so they fail the proportion test — and the fact that the firm has four letters and no reason is exactly what a reader in five years will want. That is 17.2 and 17.4 meeting, and it is the right answer. A line can be an absence in disguise, and the test for one does not find the other.'));
out.push(stage('6R', 'Share'));
out.push(p('⚠ **Read three one-line entries and ask of each whether it is a finding or a description.** ⚠ *Reconciles to 240; nothing turns on it* **is a finding.** ⚠ *Concerns petty cash* **is a description and tells a reader nothing they can use.**'));
out.push(stage('7', 'Write freely – sample (229 words)'));
out.push(sample(null, [
  'The report at my work where everything got equal space is the monthly management report, and it has nine sections of about a page each.',
  'It covers sales, debtors, stock, the vans, the counter, the two sites, staffing, suppliers and a general section. Every section has been a page every month since 2023.',
  'The part that mattered in the last six months is the debtors section, and specifically two accounts in it. In October the whole of the collection problem that cost us eight million of facility was in four lines of a one-page section, surrounded by eight other pages of things that were going normally.',
  'The ratio should have been the debtors section at two pages and everything else at a line, in the months where everything else was normal. And in the months where it was not, the ratio should have moved.',
  'What a reader did with it is the part I had not thought about. Mr Ayoub reads the first page and the figures. He told me in November that he had not known the debtor days had moved until Nadia said it in a meeting, and it had been in the report twice.',
  'It had been in the report twice and it had been on page three both times, in the same position as the stock section, which had not moved at all.',
  'A fixed shape is a shape that cannot report a change.',
]));
out.push(p('⚠ **The last line is the finding and it is better than anything in the cycle:** ⚠ *a fixed shape is a shape that cannot report a change.* **Nine sections of a page each, every month, is a report whose proportions carry no information at all** — **and the collection problem that cost the firm eight million of facility was in four lines on page three, twice, in the same position as a section that had not moved.** ⚠ **Read it aloud and then ask the class what their own monthly report cannot report.**'));
out.push(stage('7P', 'Respond'));
out.push(p('⚠ **The slip asks for the ratio and what it tells a reader.** ⚠ **Where a writer has never counted, the reviewer\'s question produces the count** — **and the count is usually worse than the writer expected, which is the useful direction for a surprise.**'));
out.push(stage('7R', 'Share'));
out.push(p('⚠ **Expect ratios worse than one to five in all three.** ⚠ **And the finding to end on: the ratio is the only part of a summary that communicates before being read** — **so a document with fixed proportions has given that away permanently.**'));

// ===================== 17.3 =====================
out.push(pb());
out.push(h2('17.3  Quoting fairly'));
out.push(stage('1', 'Get ready'));
out.push(p('**a**  Open. ⚠ **Expect the second half to produce a long pause** — **and expect at least one learner to realise they are about to discover something, which is 17.7 arriving early.**'));
out.push(p('**b**  ⚠ **The second.** ⚠ **The first is the second half of a sentence whose first half is the claim against the firm, and it is accurate.**'));
out.push(stage('2', 'Listen and read'));
out.push(p('**a**  B   **b**  1 ⚠ *The condition has been present since April 2023 and was identified in the course of this review; no occurrence was reported by any customer before March.*  2 ⚠ **The rule: a quotation that improves your side is a quotation you have not finished reading.** ⚠ **The test: would the other side quote it the same way?**'));
out.push(p('⚠ **_Every half-sentence anybody ever quoted was true_ is the line to put on the board.** ⚠ **Accuracy is not the question** — **the question is who else has the document, and in a dispute the answer is everybody.**'));
out.push(p('⚠ **The cost is the summary and not the sentence.** ⚠ **A party caught shortening one quotation has every other quotation read twice** — **and a reader who has started checking a summary has stopped using it**, **which is a loss of a different order from losing a point.**'));
out.push(p('⚠ **The test can be applied alone and that is why it is the one worth having.** ⚠ **Would the other side quote it the same way?** **Longer means you cut it. Shorter means you have found something they will not want quoted** — **and both answers are useful.**'));
out.push(p('⚠ **And it bites hardest on your own documents.** ⚠ **The only quotations in a bundle your side can be caught shortening are your own** — **which is where nobody applies the test, because nobody suspects their own file.**'));
out.push(p('**Language box – Practise (sample):**  _**Quoted:** *the count ties to the ledger.* ⚠ **In full:** *the count ties to the ledger within 0.4 per cent, which is within tolerance for a count of this size but is the largest variance in three years.* ⚠ **The half against us is the last clause, and they would quote it longer.**_'));
out.push(stage('3', 'Practise – sample with role card 2'));
out.push(dlg(null, [
  ['A', 'I have applied the test to all four of their quotations and found nothing wrong.'],
  ['B', 'Good. Now apply it to ours.'],
  ['A', 'Ours are from our own documents.'],
  ['B', 'Which documents does the other side have?'],
  ['A', 'All of them. It is a bundle.'],
  ['B', 'So which quotations can we be caught shortening?'],
  ['A', '…Ours.'],
  ['B', 'And where did you not look?'],
  ['A', 'At ours.'],
  ['B', 'The test does its work on your own file, which is the one you are not suspicious of.'],
]));
out.push(note('Five questions and A arrives at it. The instinct is to audit the opponent, which feels like the useful direction and is the safe one — their cuts will be found by your own lawyer anyway. The cuts that cost something are the ones in your own summary, from your own documents, because the other side has the originals and is reading your summary looking for exactly this. Make a class apply the test to their own writing first and in the right order: your documents, then theirs.'));
out.push(stage('3R', 'Perform'));
out.push(p('**Listener task:** ⚠ **The whole sentence with the half against the firm marked.** ⚠ **The test**, **and why it bites hardest on your own documents** — **because those are the only quotations your side can be caught shortening.**'));
out.push(stage('4', 'Your turn – sample table'));
out.push(table(['The quotation as used', 'The sentence in full', 'Which half is against you', 'Would they quote it the same way?'], [
  ['⚠ *the count ties to the ledger*', '⚠ *…within 0.4 per cent, which is within tolerance for a count of this size but is the largest variance in three years*', '⚠ **the last clause** — **largest in three years**', '⚠ **longer** — **so we cut it**'],
  ['⚠ *the auditor has no outstanding requirements*', '⚠ *the auditor has no outstanding requirements other than the Homs valuation, which has been requested in each of the last three years*', '⚠ **everything after *other than***', '⚠ **longer**'],
  ['**clause 12 in full**', '**the same**', '⚠ **none**', '⚠ **the same way** — **and the sentence after it, about nine of eleven, is ours to add**'],
], [2.2, 3, 2, 1.8]));
out.push(stage('4R', 'Report – sample'));
out.push(p('_**We quote that the count ties to the ledger. In full the sentence says within 0.4 per cent, which is within tolerance but is the largest variance in three years. The half against us is the last clause. They would quote it longer, which means we cut it.**_'));
out.push(p('⚠ **Collect both counts.** **How many of the quotations were half-sentences: usually most.** ⚠ **And how many of the writers had read the sentence in full before today?** **About half** — **and the other half had been quoting a quotation, which is 17.7.**'));
out.push(stage('5', 'Read'));
out.push(p('**1**  ⚠ **Two of the four were cut, and one of those was cut by somebody else before it reached the writer** — ⚠ **which is more serious, because a quotation shortened inside a company and repeated for years has stopped being a quotation and become a thing everybody knows.**'));
out.push(p('**2**  ⚠ **That the other side would not quote clause 11 at all** — **which told her it was not worth a paragraph and moved it into the one-line list.** ⚠ **The test does proportion work as well as fairness work, which is not obvious.**'));
out.push(p('**3**  ⚠ **That quoting fairly made the summary shorter.** ⚠ **Nine words of her own naming the half against the firm, replacing a fourteen-word half-sentence** — **and the assumed cost of fairness is length, so a case where there is none is worth recording.**'));
out.push(stage('6', 'Write with help – sample (166 words)'));
out.push(sample(null, [
  '**THE FIVE QUOTATIONS IN OUR LETTER TO THE BANK, CHECKED. 22 January. L. Barakat. Working page.**',
  '⚠ *the count ties to the ledger* | ⚠ *the count ties to the ledger within 0.4 per cent, which is within tolerance for a count of this size but is the largest variance in three years* | ⚠ **cut** — **and the clause we cut is the one a lender cares about.** **Now quoted whole.**',
  '⚠ *the auditor has no outstanding requirements* | ⚠ *…other than the Homs valuation, which has been requested in each of the last three years* | ⚠ **cut, and badly** — **the short form is not merely incomplete, it says the opposite.** **Now quoted whole, with one clause of mine: *the valuation is the only open requirement and it is three years old.***',
  '**the facility covenant, quoted in full** | **the same** | ⚠ **whole**',
  '⚠ *stock is counted monthly* | ⚠ *stock is counted monthly at Mezzeh and quarterly at Baghdad Street* | ⚠ **cut** — **and the omission is a place rather than a qualification, which is harder to spot**',
  '⚠ **Three of five were cut.** **The second is the serious one: the short form does not shorten the sentence, it reverses it.**',
  '⚠ **The test on all five: would the bank quote it the same way?** **On three they would quote it longer. On the covenant, the same.** ⚠ **And on the fourth they would ask which site, which is a question I had not left room for.**',
  '⚠ **What I have changed.** **All three now run in full.** ⚠ **The letter is eleven words longer and one sentence of it is no longer false.**',
]));
out.push(stage('6P', 'Check together – sample completed checklist'));
out.push(table(['Checklist', '✓ / ✗'], [
  ['*Quoted as* and *the sentence in full* side by side', '**✓**'],
  ['A verdict on every one', '**✓**'],
  ['Any quotation that was cut before the writer received it', '⚠ **✗** — **the page does not say who cut any of them, and three cuts in one letter suggests a habit rather than an incident**'],
  ['The test used to decide what to leave out as well', '⚠ **partly** — **the fourth produced a question rather than a decision**'],
  ['What the honest version cost, in words or in substance', '**✓** — **eleven words, and one sentence no longer false**'],
], [5, 1]));
out.push(note('The missing item matters here. Three cuts in a five-quotation letter is not an accident, and the page should say whether the writer made them or inherited them — because the remedy is different. A writer who cut them has a habit to break; a writer who inherited them from a previous letter has a company practice to find, and the practice is 17.7. The second cut is also the most serious kind in the book: "the auditor has no outstanding requirements" does not shorten the sentence, it reverses it, and a lender acting on it has been misled rather than under-informed.'));
out.push(stage('6R', 'Share'));
out.push(p('⚠ **Read one *quoted as* and then the sentence in full, and ask where the cut falls.** ⚠ **It falls at the point where the sentence stopped helping, nearly every time** — **and saying that out loud is what makes the rule memorable.**'));
out.push(stage('7', 'Write freely – sample (227 words)'));
out.push(sample(null, [
  'The thing my work quotes most is a sentence from the hospital arrangement: that benches are to be delivered flat.',
  'It comes from clause 3 of the schedule and I have never read clause 3. I have read the four words in our own delivery notes, which carry them printed at the bottom, and in Hala\'s instructions to the drivers.',
  'I went and read it this week. The clause says: benches are to be delivered flat and not upended, and any bench delivered upended is to be refused at the goods door by the receiving porter.',
  'The second half is the half nobody quotes and it is the half that matters, because it tells me whose job the refusal is. For two years we have been treating an upended bench as our problem and arguing about credits, and the clause makes it the porter\'s refusal at the door.',
  'Who shortened it is us. The four words were put on the delivery note in 2023 by somebody choosing what would fit in the space at the bottom.',
  'That is the part I keep thinking about. The cut was not an argument or a convenience. It was the width of a printed line on a form.',
  'And it has cost us two years of a conversation we did not need to have.',
]));
out.push(p('⚠ **The sixth paragraph is the finding and it is not in the unit.** ⚠ *The cut was not an argument or a convenience. It was the width of a printed line on a form.* **A half-quotation produced by the space available at the bottom of a delivery note, in 2023, and repeated for two years** — ⚠ **and the half that was left off is the half that says whose job the refusal is.** **Read it aloud: this is the mechanism of 17.7 with no bad intention anywhere in it.**'));
out.push(stage('7P', 'Respond'));
out.push(p('⚠ **The slip asks whether the other side would quote it the same way.** ⚠ **A reviewer reading somebody else\'s quotation can apply it immediately** — **and where the answer is *longer*, the follow-up is the useful one: who cut it, and when?**'));
out.push(stage('7R', 'Share'));
out.push(p('⚠ **Expect two of three not to have read the sentence in full.** ⚠ **And expect at least one to have found a cut that changes the meaning rather than shortening it** — **which is the fault 17.7 is built on, arriving from the room four cycles early.**'));

// ===================== 17.4 =====================
out.push(pb());
out.push(h2('17.4  The absence, inside the summary'));
out.push(stage('1', 'Get ready'));
out.push(p('**a**  Open. ⚠ **Expect the second half to produce a name and a length of service** — **and expect somebody to notice that the firm\'s memory of the thing has a retirement date.**'));
out.push(p('**b**  ⚠ **The second.** ⚠ *There may be other material not before us* **is a sentence that protects the writer and informs nobody.** ⚠ **A date, a name and *on either side* is a fact.**'));
out.push(stage('2', 'Listen and read'));
out.push(p('**a**  B   **b**  1 ⚠ **Because a summary that lists what the bundle contains and not what it lacks tells the reader the bundle is complete, and the one thing the firm knows is that it is not.**  2 ⚠ **She wants to put what she remembers of the call into the summary; he refuses** — **a summary is about what the bundle says and does not say, and a recollection is a separate dated document with her name on it.**'));
out.push(p('⚠ **The four words are the technique:** ⚠ *and the absence is ours.* **They answer the question the reader is about to ask, in the form the writer would choose rather than the form the reader would** — **and that question only gets worse if the reader reaches it first.**'));
out.push(p('⚠ **The separation of summary and recollection is a point about document types and it is worth being strict about.** ⚠ **A summary says what the bundle says and does not say; a recollection is evidence of a different kind** — **and mixing them produces a document that is neither and is worth nothing as either.**'));
out.push(p('⚠ **_Written today, which is eight months late and is the earliest it can now be written_ is the sentence to admire.** ⚠ **It concedes the lateness, dates it, and refuses the only alternative, which is no note at all** — **and a note written late and dated honestly is worth more than nothing, which is the actual choice.**'));
out.push(p('⚠ **And the risk argument is the one learners resist.** ⚠ **Being wrong about an absence beats being silent about one** — **if the other side produces a note of the call, the sentence is wrong and they say so, and the firm has been wrong about a fact rather than silent about one.** **Only the first survives.**'));
out.push(p('**Language box – Practise (sample):**  _**What happened:** Mr Attar said in the 2023 meeting that he would accept an internal estimate for one more year._ ⚠ _**On either side:** nothing in writing._ ⚠ _**The sentence:** there is no record on either side of the indication given in the 2023 meeting, and the absence is ours._ ⚠ _**The recollection:** a separate note, dated today, in three parts._'));
out.push(stage('3', 'Practise – sample with role card 1'));
out.push(dlg(null, [
  ['A', 'I am going to leave it out. It is our best point and we cannot prove it.'],
  ['B', 'Is it a point?'],
  ['A', 'It would be, if we had a note.'],
  ['B', 'You have not got a note, so what is it?'],
  ['A', 'A gap.'],
  ['B', 'Whose?'],
  ['A', 'Ours. I made the call.'],
  ['B', 'So it goes in, as a fact about the bundle, with four words saying whose it is.'],
  ['A', 'And Mr Ayoub will ask why I did not note it.'],
  ['B', 'He will ask it anyway. The four words decide whether he asks it kindly.'],
]));
out.push(note('"He will ask it anyway. The four words decide whether he asks it kindly" is the argument that works with a class, because it is about the conversation rather than about candour. The question is coming either way; what is in the writer\'s control is whether it arrives as a question about a gap that has been declared or as a discovery about a gap that was hidden. Those two conversations go very differently and every learner has been in both of them.'));
out.push(stage('3R', 'Perform'));
out.push(p('**Listener task:** ⚠ **The absence in one sentence, with the four words.** ⚠ **The recollection goes in a separate dated note.** ⚠ **And being wrong beats being silent, because only one of the two survives being found out.**'));
out.push(stage('4', 'Your turn – sample table'));
out.push(table(['What happened, and when', 'Is it on either side?', 'The absence sentence', 'Where the recollection goes'], [
  ['⚠ **Mr Attar indicated in the 2023 meeting that he would accept an internal estimate for one more year**', '⚠ **nothing in writing on either side**', '⚠ *There is no record on either side of the indication given in the 2023 meeting, and the absence is ours.*', '**a separate note, dated today, in three parts**'],
  ['⚠ **the Jaramana pharmacy was told in 2024 that Monday deliveries would continue**', '⚠ **nothing** — **and they have had one every week for two years**', '⚠ *There is no written arrangement with the Jaramana pharmacy at all; the absence is ours.*', '⚠ **a note, and then an actual arrangement, which is better**'],
], [2.4, 1.6, 3, 2.2]));
out.push(stage('4R', 'Report – sample'));
out.push(p('_**In 2023 Mr Attar indicated that he would accept an internal estimate for one more year. It is in no document on either side. The sentence is: there is no record on either side of the indication given in the 2023 meeting, and the absence is ours. What I remember goes in a separate note dated today.**_'));
out.push(p('⚠ **Two counts.** **How many absences belonged to the writer\'s own side: nearly all.** ⚠ **And how many had ever been written down as absences? None** — **because an absence is not a thing anybody files, which is exactly why it has to be put in a document that is about something else.**'));
out.push(stage('5', 'Read'));
out.push(p('**1**  ⚠ **The absence · whose it is · and where the recollection is.** ⚠ **Three sentences, about fifty words, on the first page** — **and the third is what stops the first two reading as an excuse, because it points at a document.**'));
out.push(p('**2**  ⚠ **_What I am sure of · what I believe and cannot be sure of · what I am sure I did not say_.** ⚠ **The second part names the precise uncertainty** — *before the agreement* **or** *before the summer* — **and says the difference matters and she will not pretend to a certainty she does not have.**'));
out.push(p('**3**  ⚠ **That the call produced nothing she had to act on, so there was nowhere for it to go** — **the same reason the counter does not record the plater\'s shortfalls and nobody wrote down Ms Tannous\'s September call.** ⚠ **And she says it is a fault in how the office works and not in what she did on 14 May**, **which is the difference between a mechanism and an apology.**'));
out.push(stage('6', 'Write with help – sample (181 words)'));
out.push(sample(null, [
  '**ONE: THE SENTENCE IN THE SUMMARY.**',
  '⚠ **There is no record on either side of the indication given by the auditor in the 2023 meeting, that an internal estimate of the Homs value would be accepted for one further year. The absence is ours: we were in the meeting and we took no minute of it. A separate note of what is recollected is at page 3, dated 22 January.**',
  '**TWO: THE SEPARATE NOTE. 22 January. L. Barakat.**',
  '⚠ **NOTE OF AN INDICATION GIVEN IN THE AUDIT MEETING OF 14 MARCH 2023, WRITTEN ON 22 JANUARY.**',
  '⚠ **This note is written twenty-two months after the meeting and after the same requirement has been raised twice more. It is the earliest it can now be written and I am recording that at the top.**',
  '⚠ **What I am sure of.** **That the meeting took place on 14 March 2023 at this office, that Mr Attar, Mr Ayoub and I were present, and that the Homs carrying value was discussed.** **The meeting is in the office diary and that is the only document of any kind that relates to it. [diary, 14 March 2023]**',
  '⚠ **What I believe and cannot be sure of.** **That he said an internal estimate would do for one more year.** ⚠ **I am not sure whether he said *one more year* or *this year*, and the difference is the whole of the point, and I will not pretend to a certainty I do not have.**',
  '⚠ **What I am sure I did not say.** **I did not ask him to confirm it in writing, and nobody else did.**',
  '⚠ **Why there is no note.** **The meeting produced nothing anybody had to do, so there was nowhere for it to go.** ⚠ **That is the same reason there is no note of the Tannous call of September and no record of the plater\'s shortfalls** — **a fault in how this office works, and not in what happened on 14 March.**',
]));
out.push(stage('6P', 'Check together – sample completed checklist'));
out.push(table(['Checklist', '✓ / ✗'], [
  ['Three sentences in the summary: absence, whose, where the note is', '**✓**'],
  ['Both dates at the top of the note', '**✓** — **and *after the same requirement has been raised twice more*, which the frame does not ask for**'],
  ['The three parts, including *what I am sure I did not say*', '**✓** — **and it is the strongest part: nobody asked for it in writing**'],
  ['The one document that does exist, and what it does not prove', '**✓** — **the diary entry**'],
  ['Why there was no note, as a mechanism', '**✓**'],
], [5, 1]));
out.push(note('"What I am sure I did not say: I did not ask him to confirm it in writing, and nobody else did" is the best line in the sample and it is the part learners leave out. The third section is supposed to bound the recollection, and here it does something more — it concedes the only real criticism available, which is that the firm had the chance to get the indication in writing and did not take it. A recollection that concedes that is much harder to dismiss than one that does not, and the concession costs nothing because the fact is obvious to anybody reading.'));
out.push(stage('6R', 'Share'));
out.push(p('⚠ **Read the *what I believe and cannot be sure of* sections and ask whether the uncertainty is named precisely.** ⚠ *One more year* **against** *this year* **is precise; *I cannot remember exactly* is not** — **and the whole credibility of the note rests on the difference.**'));
out.push(stage('7', 'Write freely – sample (231 words)'));
out.push(sample(null, [
  'The important thing at my work that is in no document is the arrangement with the Jaramana pharmacy.',
  'They take a Monday delivery every week and have done for two years. There is no order, no terms, no credit agreement and no price list. The price they pay is the price Hala quotes them, which is the counter price, and the delivery is made because Fadi passes the door.',
  'Who knows is Hala and Fadi. Hala knows the price history and Fadi knows that the pharmacy opens at eight and will not take a delivery before it does.',
  'The nearest document is the delivery note, which Fadi writes out by hand each week and which the pharmacy signs. Two years of them are in the folder, by month.',
  'Why nothing was written is the reason from this cycle: nobody ever had to do anything about it. It started as a favour on a route and it has never produced a decision, a dispute or a credit, so there has been nowhere for it to go.',
  'What I would write now is not a note. It is an actual arrangement: a price, a delivery day, and what happens when Fadi is away, which is the thing nobody has ever had to answer.',
  'And the absence is ours, and it is worth about 160,000 a year, which I worked out from the folder this week and nobody at this company knew.',
]));
out.push(p('⚠ **This sample does the thing the cycle cannot ask for: it concludes that the remedy is not a note.** ⚠ **An undocumented arrangement worth 160,000 a year needs an arrangement, not a recollection** — **and the learner has distinguished the two correctly.** ⚠ **The last clause is the finding:** *I worked it out from the folder this week and nobody at this company knew.* **Two years of handwritten delivery notes in a folder by month, and the figure was always there.**'));
out.push(stage('7P', 'Respond'));
out.push(p('⚠ **The slip asks whose the absence is.** ⚠ **Expect *ours* in nearly every case**, **and the useful follow-up is the one from the mediation: why was there nowhere for it to go?** **The answer is always the same mechanism and it is worth hearing three times.**'));
out.push(stage('7R', 'Share'));
out.push(p('⚠ **Expect all three absences to be the writer\'s own side\'s, and expect the same reason in each:** ⚠ **the thing produced nothing to act on, so there was nowhere for it to go.** **Three units of this book have now found the same fault** — **14.7, 15.7 and here — and it is worth naming as the fault of the whole course.**'));

// ===================== 17.5 =====================
out.push(pb());
out.push(h2('17.5  The summary read without the original'));
out.push(stage('1', 'Get ready'));
out.push(p('**a**  Open. ⚠ **Everybody has read one, and the second half of the question produces the list the cycle is about** — **the sentences that could only be taken on trust.**'));
out.push(p('**b**  ⚠ **The second.** ⚠ *The gate sheets support our position* **passes every accuracy check and cannot be acted on, repeated or argued with.**'));
out.push(stage('2', 'Listen and read'));
out.push(p('**a**  B   **b**  1 ⚠ *Could I act on this sentence if the bundle were in a box in Homs?*  2 ⚠ **The credit note of 58,000, which she read as a part payment of a 2.1 million claim** — **because that is the natural reading, and it was a line in the irrelevant list precisely because it did not matter.**'));
out.push(p('⚠ **This cycle cannot be done alone and that is the point of it.** ⚠ **All four failed sentences looked right to the writer, because the writer knows what the referred-to documents say** — **and no amount of rereading will find them.**'));
out.push(p('⚠ **The fault has a name: a sentence that refers to a document instead of saying what it says.** ⚠ *Support · key document · in our favour · immaterial* **are all verdicts or labels**, **and a reader without the bundle can do nothing with any of them.**'));
out.push(p('⚠ **And misreadability is a new question, with no section in most summaries.** ⚠ **Proportion decides what gets a paragraph; misreadability decides what gets a sentence, whether the document deserves one or not** — **and the two point in opposite directions on the credit note, which is of no consequence and is the most dangerous thing in the bundle.**'));
out.push(p('⚠ **58,000 against 2.1 million looks like a firm that has started paying.** ⚠ **Say the natural misreading out loud when teaching this**, **because learners will not believe that a reader could make it until they hear it.**'));
out.push(p('**Language box – Practise (sample):**  _**Was:** *the schedules support the carrying value.* ⚠ **Could not be used:** supported how? ⚠ **Is:** *schedule 4 carries Homs at 2.4 million on an internal estimate of 2021; no third-party valuation exists. [p. 18]*_'));
out.push(stage('3', 'Practise – sample with role card 2'));
out.push(dlg(null, [
  ['A', 'Our credit note of 10 October, 58,000, is in the bundle at page 95.'],
  ['B', 'So we have paid them 58,000.'],
  ['A', 'No. That is the marking credit from September.'],
  ['B', 'There is nothing in your sentence that says so.'],
  ['A', 'It is in the nineteen, with a line.'],
  ['B', 'I have not read the nineteen. I have read page one.'],
  ['A', 'Nobody would assume we had started paying.'],
  ['B', 'I did, ten seconds ago, and I know this file.'],
  ['A', 'Then it belongs on page one.'],
  ['B', 'In a sentence that says what it is not.'],
]));
out.push(note('"I did, ten seconds ago, and I know this file" is the line that settles it. The writer\'s objection — nobody would assume that — is answered by the fact that somebody just did, and that the somebody was the best-informed reader available. A misreading made by an informed reader will certainly be made by an uninformed one, and the remedy is a sentence that says what the document is not. It costs fifteen words and it goes on page one, which is the one thing the proportion rule would never have allowed.'));
out.push(stage('3R', 'Perform'));
out.push(p('**Listener task:** ⚠ **The test in one sentence.** ⚠ **Proportion decides paragraphs; misreadability decides sentences** — **and a document of no consequence can need a sentence on page one, which is the one case the proportion rule gets wrong.**'));
out.push(stage('4', 'Your turn – sample table'));
out.push(table(['The sentence', 'Why it cannot be used', 'The rewrite, with its reference', 'Mis-read as?'], [
  ['⚠ *the schedules support the carrying value*', '⚠ **supported how?** — **a verdict with no content**', '**schedule 4 carries Homs at 2.4 million on an internal estimate of 2021; no third-party valuation exists [p. 18]**', '**—**'],
  ['⚠ *the auditor\'s requirement is outstanding*', '⚠ **which requirement, and since when?**', '**a valuation of the Homs site has been required in each of the last three years, in the same words [pp. 18, and 2022 p. 14, 2023 p. 16]**', '**—**'],
  ['**the 2023 restatement is at page 81**', '⚠ **usable, but** —', '**the 2023 comparatives were restated on one basis; a reader comparing 2022 with 2024 without page 81 will find a discrepancy that is not there [p. 81]**', '⚠ **as an error in the comparatives**'],
], [2.2, 2, 3, 1.8]));
out.push(stage('4R', 'Report – sample'));
out.push(p('_**My partner could not use three sentences. The worst was "the schedules support the carrying value", because support is a verdict with no content. The rewrite names the schedule, the figure and the absence. And the restatement at page 81 was read as an error in the comparatives, which is a misreading and not a question of consequence.**_'));
out.push(p('⚠ **Collect the total and then ask the question that lands.** **How many of the writers had believed their summaries stood alone?** ⚠ **All of them** — **which is the cycle: the belief is universal and the test takes twenty minutes of somebody else\'s time.**'));
out.push(stage('5', 'Read'));
out.push(p('**1**  ⚠ **Every one refers to a document instead of saying what it says.** ⚠ *Support · key document · in our favour · immaterial* — **four verdicts or labels**, **and a reader without the bundle can act on none of them.**'));
out.push(p('**2**  ⚠ **That misreadability is not the same question as consequence and the summary had no place for it.** ⚠ **Proportion decides what gets a paragraph; misreadability decides what gets a sentence whether the document deserves one or not** — **and the two can point in opposite directions, as they do on the credit note.**'));
out.push(p('**3**  ⚠ **That all four failed sentences looked right to her, because she knows what the documents say** — ⚠ **and that the fifth was worse, because she had put it where nobody would check it precisely on the ground that it did not matter.**'));
out.push(stage('6', 'Write with help – sample (173 words)'));
out.push(sample(null, [
  '**SUMMARY, THIRD DRAFT: WHAT THE FILE-SHUT READING FOUND. 23 January. L. Barakat. Working page.**',
  '⚠ **Nadia read the three pages on the 22nd with the file shut. Three sentences failed and one was read the opposite way. Fifteen minutes.**',
  '⚠ *the schedules support the carrying value* | **schedule 4 carries Homs at 2.4 million on an internal estimate of 2021; no third-party valuation exists [p. 18]** | ⚠ **_support_ is a verdict with no content** — **she asked *supported how* and I had no sentence to give her**',
  '⚠ *the auditor\'s requirement is outstanding* | **a valuation has been required in each of the last three years, in the same words [pp. 18, 2022 p. 14, 2023 p. 16]** | ⚠ **_outstanding_ told her it existed and not what it was or how old**',
  '⚠ *the stock count is satisfactory* | **the count ties to the ledger within 0.4 per cent, the largest variance in three years [pp. 40–44]** | ⚠ **_satisfactory_ is a word she had to take on trust, and the honest version is less comfortable**',
  '⚠ **And the one read the opposite way.** **The 2023 restatement was a line in the twenty-seven.** ⚠ **She read it as an error in the comparatives, which is the natural reading of the word *restated*.** **It is now a sentence on page 1.**',
  '⚠ **The finding.** ⚠ **Two of the three rewrites are LESS favourable to us than the originals** — *the largest variance in three years* **and** *three years in the same words* — **and both are what a reader needed.** **I had not understood that the referring sentences were doing concealment and not compression.**',
  '⚠ **One thing I could not have found alone.** **All three looked right to me.**',
]));
out.push(stage('6P', 'Check together – sample completed checklist'));
out.push(table(['Checklist', '✓ / ✗'], [
  ['The reader, the date and the duration', '**✓** — **fifteen minutes**'],
  ['A named fault in every *why*, not a judgement', '**✓**'],
  ['The opposite-way reading, with the natural reading spelled out', '**✓** — ***restated* reads as *corrected***'],
  ['The finding about shape', '⚠ **different, and better** — **the referring sentences were concealing rather than compressing**'],
  ['What the writer could not have found alone', '**✓**'],
], [5, 1]));
out.push(note('That fourth row is a finding the unit does not reach and it is worth teaching from. Two of the three rewrites are less favourable to the firm than the vague originals: "satisfactory" concealed the largest variance in three years, and "outstanding" concealed that the requirement was three years old. The writer had assumed the referring sentences were compression; they were concealment, and she had not intended any of it. That is the strongest possible reason to have somebody read a summary with the original shut, and it is stronger than the usability argument the cycle makes.'));
out.push(stage('6R', 'Share'));
out.push(p('⚠ **Read the *why* columns and look for the vague words.** ⚠ *Support · satisfactory · outstanding · immaterial · appropriate · adequate* — **a summary with three of those in it is concealing something, usually from its own author.**'));
out.push(stage('7', 'Write freely – sample (228 words)'));
out.push(sample(null, [
  'The summary I read without the document behind it was the tender evaluation at the hospital, which they sent us after we lost one in 2024.',
  'It was two pages and it said that our offer was compliant, that the successful offer was compliant, and that the successful offer offered better value.',
  'What I had to take on trust was all of it, and particularly the word value, which was not defined anywhere in the two pages.',
  'What I could not use was the one thing I wanted, which was why we lost. Compliant and compliant and better value tells me nothing I can change.',
  'Did I ask? I telephoned and asked what value meant and the officer said it was price and delivery together. So I asked what the delivery difference was and she said the other supplier offered fourteen days and we offered twenty-one.',
  'That was the whole thing. Two pages that cost somebody an afternoon, and the sentence that mattered was never in them: our delivery was a week longer.',
  'What she could have done in a clause is write it: the successful offer was 2 per cent higher on price and seven days shorter on delivery. Nineteen words, and I would have changed the delivery term the same week instead of eleven months later.',
  'I changed it in November, after this conversation, and we won the next one.',
]));
out.push(p('⚠ **This is the sample for the whole cycle because the learner is the reader rather than the writer.** ⚠ **Two pages of *compliant* and *better value*, and the one sentence that mattered was never in them** — *our delivery was a week longer* — **nineteen words, obtainable by one telephone call, and it cost eleven months.** ⚠ **And the last line is the measurement:** *I changed it in November and we won the next one.*'));
out.push(stage('7P', 'Respond'));
out.push(p('⚠ **The slip asks whether the reader could act on the sentence with the original shut.** ⚠ **It is the cycle\'s own test applied by somebody who genuinely does not have the original** — **which is the only condition under which it works, and a pair of learners can give each other exactly that.**'));
out.push(stage('7R', 'Share'));
out.push(p('⚠ **Expect one of three to have asked.** ⚠ **And the finding to end on: in the other two the reader either acted on a sentence they could not use or did not act at all** — **and the writer never found out which, which is why this fault survives a career.**'));

// ===================== 17.6 =====================
out.push(pb());
out.push(h2('17.6  Summarising a case you disagree with'));
out.push(stage('1', 'Get ready'));
out.push(p('**a**  Open. ⚠ **The second half is the task and it is harder than it sounds** — **expect the first attempt to contain the answer, and expect the learner not to notice.**'));
out.push(p('**b**  ⚠ **The second.** ⚠ *They allege, without any evidence* **has answered the claim in six words**, **and a reader can see the answer through the summary.**'));
out.push(stage('2', 'Listen and read'));
out.push(p('**a**  B   **b**  1 ⚠ **In the answer, numbered against the claim** — **and the claim comes first, because a reader who meets the answer first never learns what the claim was.**  2 ⚠ **Because if the other side could read your summary of their case without complaining, it is a summary** — **and if they would say *that is not what we are saying*, it is your answer with their name on it.**'));
out.push(p('⚠ **_Allege_, _assert_ and _purport_ all mean *and they are wrong*.** ⚠ **Three in one sentence is not emphasis; it is a summary that has already answered the thing it was summarising** — **and the arbitrator will read the answer through it, which costs the firm the answer it was going to make properly later.**'));
out.push(p('⚠ **The two neutral forms to drill are *the claim is that* and *the document relied on is*.** ⚠ **The second is usually the sentence that matters most to your own side**, **because what the other side relies on is what you have to deal with** — **and in this bundle it is Sham Trading\'s own root-cause paper.**'));
out.push(p('⚠ **Claim first, answer second, always.** ⚠ **A reader who meets the answer first reconstructs the claim from it** — **and that reconstruction is the one version of the claim nobody should be working from, including your own side in a meeting.**'));
out.push(p('⚠ **And the test is the recognition test from 16.4, which is harder here.** ⚠ **In a steelman you want the holder to recognise themselves; here you would rather they did not** — **and the test does not care what you want.** **Say that plainly, because learners will try to soften it.**'));
out.push(p('**Language box – Practise (sample):**  _**The complaint:** that we have been charging the hospital the counter price for benches since 2024._ ⚠ _**As I first wrote it:** they allege that we have overcharged, without having read the schedule._ ⚠ _**The claim is that** the benches have been invoiced at the counter rate rather than the schedule rate since March 2024. **The document relied on is** our own invoice run._'));
out.push(stage('3', 'Practise – sample with role card 2'));
out.push(dlg(null, [
  ['A', 'I have put our answers in with the claim. They are short and obvious.'],
  ['B', 'Read me your summary of their case without the answers.'],
  ['A', '…Then it is four lines instead of nine.'],
  ['B', 'And what does Mr Ayoub know about the claim from the nine?'],
  ['A', 'That it is wrong.'],
  ['B', 'And what is it?'],
  ['A', 'It is in there, in the subordinate clauses.'],
  ['B', 'So he reconstructs it from your answer.'],
  ['A', 'Which is the one version nobody should be working from.'],
  ['B', 'Including you, in the meeting, when they put it properly.'],
]));
out.push(note('The last line is the practical cost and it is the one that persuades. A firm that has only ever read its own answer to a claim has never read the claim, and the first time anybody states it properly will be in the room, from the other side, with everybody surprised. The exercise of writing the claim without the answer is not a courtesy to the claimant; it is the only way your own side finds out what is being said. Ask the class what the claim against their firm actually is and watch how many can state it without answering it.'));
out.push(stage('3R', 'Perform'));
out.push(p('**Listener task:** ⚠ **The claim in two sentences with no verdict in either.** ⚠ **The answer goes in a separate numbered document.** ⚠ **And the test: could they read it without complaining?**'));
out.push(stage('4', 'Your turn – sample table'));
out.push(table(['The complaint, as you would put it', 'The claim, in their terms', 'What they rely on', 'Could they read it without complaint?'], [
  ['⚠ **they say we overcharged, without reading the schedule**', '⚠ **the claim is that benches have been invoiced at the counter rate rather than the schedule rate since March 2024**', '⚠ **our own invoice run, and the schedule**', '⚠ **yes**'],
  ['⚠ **they claim we were late, ignoring the weather**', '⚠ **the claim is that nine of eleven deliveries in January and February arrived after noon, against a schedule requirement of before noon**', '⚠ **the goods-door log, which is theirs**', '⚠ **yes** — **and the weather is our answer, not their claim**'],
], [2.4, 2.8, 2.2, 1.8]));
out.push(stage('4R', 'Report – sample'));
out.push(p('_**The complaint is about the bench prices. As I first wrote it, it had two verdicts in it. The claim is that benches have been invoiced at the counter rate rather than the schedule rate since March 2024. The document relied on is our own invoice run. They could read it without complaining.**_'));
out.push(p('⚠ **Collect both counts.** **How many first versions contained a verdict verb: most.** ⚠ **And how many contained the answer as well?** **Most of those too** — **and the two faults are the same fault: a writer who disagrees cannot leave the disagreement out without being made to.**'));
out.push(stage('5', 'Read'));
out.push(p('**1**  ⚠ **The claim · the documents relied on · the point they put highest · and what they do not claim.** ⚠ **The last of those is not in the claim at all** — **it is the writer\'s reading of what the claimant has chosen not to say, and it is the most useful part of the page.**'));
out.push(p('**2**  ⚠ **That they do not rely on clause 11 at all, although it is in the bundle.** ⚠ **A clause in the bundle that the claimant does not rely on tells you what their advisers think of it** — **and here it means they know the inspection right was never exercised and would rather not raise it.**'));
out.push(p('**3**  ⚠ *We have no answer to this and I am recording that rather than drafting round it.* ⚠ **Fourteen words** — **and the alternative is a paragraph that looks like an answer, which the firm\'s own side will then rely on in a meeting.**'));
out.push(stage('6', 'Write with help – sample (187 words)'));
out.push(sample(null, [
  '**ONE: THEIR CASE, SUMMARISED. 24 January. L. Barakat. One page. No answers on this page.**',
  '⚠ **The claim is that 118 benches delivered between March 2024 and December were invoiced at the counter rate of 2,400 rather than the schedule rate of 2,150, and that the difference of 29,500 is repayable. [their letter of 14 January]**',
  '⚠ **The documents relied on are two.** **Our own invoice run for the period, which they have because every invoice went to them. And schedule 2 of the arrangement, which sets the rate and which neither side has amended.**',
  '⚠ **The point they put highest is not the money.** **It is that the rate changed in March 2024 without any notice to them.** ⚠ **Their words: *the Supplier altered a scheduled rate unilaterally and continued to invoice at it for nine months.* [their letter, paragraph 3]**',
  '⚠ **What they do not claim.** **They do not claim that the benches were defective or late. They do not claim interest. And they do not rely on the termination provision at all, although their letter cites the arrangement generally.** ⚠ **The third is the most useful line on this page: nine months of unilateral overcharging would be the obvious ground for it, and they have not taken it.**',
  '**TWO: OUR ANSWER, NUMBERED AGAINST THE CLAIM. 24 January.**',
  '⚠ **To the rate:** ⚠ **we have no answer. The schedule rate is 2,150, the invoices are at 2,400, and nobody here can say who changed it or when.**',
  '⚠ **To the notice point:** **no notice was given because nobody knew a change had been made.** ⚠ **That is an explanation and not a defence, and I am marking it as one.**',
]));
out.push(stage('6P', 'Check together – sample completed checklist'));
out.push(table(['Checklist', '✓ / ✗'], [
  ['*No answers on this page* at the head, and none on it', '**✓**'],
  ['The documents relied on, listed', '**✓** — **and both are effectively ours**'],
  ['The point they put highest, in their own words', '**✓**'],
  ['*What they do not claim*, with at least three items', '**✓** — **and the third is read correctly**'],
  ['An answer that says *we have no answer* where that is true', '**✓** — **twice, and the second is marked as an explanation and not a defence**'],
], [5, 1]));
out.push(note('Two things to point at. The reading of what they do not claim is exactly right: nine months of unilateral overcharging is the obvious ground for terminating, and a claimant who does not take it is telling you they want the money and not the exit. That is worth more than any answer on the second page. And "that is an explanation and not a defence, and I am marking it as one" is the discipline of the whole unit in one clause — the firm\'s only account of itself is that nobody knew, which is true, and a writer who lets it stand unlabelled has handed their own side a defence that will collapse in the room.'));
out.push(stage('6R', 'Share'));
out.push(p('⚠ **Read the claim sentences and listen for two things: a verdict verb, and an answer smuggled into a subordinate clause.** ⚠ *The claim is that we overcharged, although the schedule was never amended* **has the answer in it** — **and the clause after *although* is the giveaway every time.**'));
out.push(stage('7', 'Write freely – sample (233 words)'));
out.push(sample(null, [
  'The complaint made about my work is from the chamber of commerce, about our quarterly returns.',
  'The claim is that four of the last eight quarterly returns were filed after the fifteenth of the month following the quarter, and that one, for the quarter to September, was not filed at all until January.',
  'The documents relied on are their own receipt register and our returns, which carry our date stamp.',
  'The point they put highest is not the lateness. It is that the September return, when it came, was signed and dated 15 October, which is the day it was due and not the day it was sent. Their words: the return bears a date nine weeks before the date of receipt.',
  'What they do not claim. They do not claim the figures are wrong. They do not propose any penalty, although their rules provide for one. And they do not mention the two returns that were filed early, which are in the same register.',
  'Our answer, separately: on the four late returns, we have no answer and they are late. On the date on the September return, the date is the date I prepared it and it sat in the drawer until January, which is true and is the thing I would least like to have to say.',
  'Writing their case without answering it took twenty minutes and I understood the complaint for the first time at the end of it.',
]));
out.push(p('⚠ **The last line is the finding and it is the one the cycle exists for:** ⚠ *writing their case without answering it took twenty minutes and I understood the complaint for the first time at the end of it.* ⚠ **And the point they put highest is not the one the firm had been worrying about** — **not the lateness but the date on the document, which is a different and much worse allegation.** **That is the pattern: a firm defending the wrong point has spent its effort on something nobody is pressing.**'));
out.push(stage('7P', 'Respond'));
out.push(p('⚠ **The slip asks whether the complainant could read it without complaining.** ⚠ **A reviewer can answer it by reading the summary as the complainant** — **and the commonest failure is not a verdict verb but the absence of the point the complainant actually puts highest.**'));
out.push(stage('7R', 'Share'));
out.push(p('⚠ **Expect two of three to find that the point the complainant puts highest is not the one the firm was worrying about.** ⚠ **Say what that costs: a firm defending the wrong point has spent its effort on something nobody is pressing** — **and it only finds out in the room.**'));

// ===================== 17.7 =====================
out.push(pb());
out.push(h2('17.7  Review & Mediate: the sentence everybody quotes'));
out.push(stage('1', 'Get ready – Unit 17 quiz'));
out.push(p('**1** ⚠ **An index is organised by document, a summary by question** — **and the test is whether a decision taken on the summary alone would be the same decision.**  **2** ⚠ *If it did not exist, would the answer change?* — **and relevance gets a document into a bundle where consequence earns it a paragraph.**  **3** ⚠ **A quotation that improves your side is one you have not finished reading** — **and the test is whether the other side would quote it the same way.**  **4** ⚠ **The absence · whose it is · where the recollection is** — **and the recollection goes in a separate dated note.**  **5** ⚠ **The sentences that refer to a document instead of saying what it says** — **and misreadability is a separate question from consequence.**  **6** ⚠ **_Allege_, _assert_, _purport_** — **and the answers go in a separate numbered document, after the claim.**'));
out.push(stage('2', 'Listen and read'));
out.push(p('**a**  B   **b**  1 ⚠ **Everybody in the office, for two years** — **and it is in three of their own letters and in the facility paper sent to the bank in June.**  2 ⚠ **That it is the first half of his sentence and the half left off is the half he wrote it for** — ⚠ **and he refuses to write a letter explaining it, because that would make him a witness in a dispute about a company he audits.**'));
out.push(p('⚠ **This is the quietest mediation in either book and the most alarming finding in the level.** ⚠ **A half-sentence repeated inside a company for two years is no longer a quotation: it is a thing everybody knows** — **and nobody checks a thing everybody knows.**'));
out.push(p('⚠ **Mr Attar\'s response is the model and it is four words:** ⚠ *read it to me from the note.* **He does not defend the sentence, dispute the use of it, or ask who did it** — **he asks for the document, and the document settles it in one reading.**'));
out.push(p('⚠ **Trace how the half travelled, because that is the part that is generalisable.** ⚠ **Three of the firm\'s own letters, a facility paper to the bank, and now an arbitration bundle** — **and the claimant is quoting Sham Trading\'s quotation of Mr Attar.** **No bad intention anywhere in the chain.**'));
out.push(p('⚠ **His refusal is the most instructive thing in the exchange and the hardest for a class to accept.** ⚠ **A letter explaining his own sentence makes him a witness in a dispute about a company he audits, and his independence is worth more to the firm than his explanation** — **which is a cost a layman never sees and a professional sees immediately.**'));
out.push(p('⚠ **And the remedy is not a correction.** ⚠ *The remedy is that somebody reads it.* **The note has always said what it says and it is in the bundle in full at page 177** — **and in eleven years nobody in the office read page four, because they all read a quotation of it in each other\'s letters.**'));
out.push(stage('3', 'Practise – sample'));
out.push(dlg(null, [
  ['Nour', 'We quote one sentence of your note constantly. The gate sheet is the primary record.'],
  ['Mr Attar', 'That is not a sentence I have ever written. Read it to me from the note.'],
  ['Nour', 'The gate sheet is the primary record of what left the yard, and is not a record of condition.'],
  ['Mr Attar', 'The half you leave off is the half I wrote it for.'],
  ['Nour', 'Dallal are relying on the half we quote.'],
  ['Mr Attar', 'You gave it to them. It is in three of your own letters.'],
  ['Nour', 'Will you write and explain it?'],
  ['Mr Attar', 'No. That makes me a witness about a company I audit.'],
  ['Nour', 'So the remedy is the note.'],
  ['Mr Attar', 'The remedy is that somebody reads page four.'],
]));
out.push(note('Ten lines and no raised voice. The thing to make a class notice is how little Mr Attar does: he does not establish who shortened it, does not ask why nobody checked, and does not offer help. He asks for the document, names the omission, declines the one thing he is asked for, and gives the remedy in six words. That is what authority looks like when it is exercised by somebody whose value depends on not being drawn in — and his refusal protects the firm, which is the part learners miss entirely on first reading.'));
out.push(stage('3R', 'Perform'));
out.push(p('**Listener task:** ⚠ **The whole sentence, with the second half underlined.** ⚠ **Where the short form travelled: three letters, a facility paper, and the bundle.** ⚠ **And why he will not write a letter** — **it makes him a witness, and his independence is worth more than his explanation.**'));
out.push(stage('4', 'Your turn – sample table'));
out.push(table(['The quotation as used', 'The sentence in place', 'Where the short form has travelled', 'Who shortened it first'], [
  ['⚠ *the gate sheet is the primary record*', '⚠ *…of what left the yard, and is not a record of condition* — **audit note 2024, p. 4**', '⚠ **three of our own letters · the June facility paper · the bundle at p. 177 in the short form**', '⚠ **unknown** — **the earliest short form is our own letter of May 2024**'],
  ['⚠ *benches to be delivered flat*', '⚠ *…and not upended, and any bench delivered upended is to be refused at the goods door by the receiving porter* — **schedule 3**', '⚠ **the printed delivery note · the drivers\' instructions**', '⚠ **us, in 2023** — **and the cut was the width of a line on a form**'],
], [2.2, 2.8, 2.4, 1.8]));
out.push(stage('4R', 'Report – mediation'));
out.push(p('⚠ **The unwritten thing:** ⚠ **the most dangerous sentence in any company is the one everybody quotes and nobody has read in place** — **because a quotation repeated inside an organisation stops being a quotation and becomes a thing everybody knows, and nobody checks a thing everybody knows.** ⚠ **So six cycles about summarising two hundred and fourteen pages end at page four of an eleven-year-old note**, **and the remedy is not a correction or a letter but one person going and reading it.**'));
out.push(p('⚠ **Word list, fifth six: _a reader who will not read the original · proportion in a summary · the part against us · an absence inside a summary · a page reference · a sentence nobody has read in place_.** **Thirty of seventy-two.**'));
out.push(stage('5', 'Read – exam practice (B2 Business Vantage Reading Part 2)'));
out.push(p('**The answers.**'));
out.push(table(['**Q**', '1', '2', '3', '4', '5'], [['Answer', 'C', 'A', 'F', 'D', 'B']], [1.4, 0.9, 0.9, 0.9, 0.9, 0.9]));
out.push(p('**The sentence not needed is E.**'));
out.push(p('⚠ **Four of the five are solved by the sentence AFTER the gap, which is the opposite of the usual advice and is what this text is built to teach.** **Gap 2 is followed by *where it would not*, which requires a conditional before it. Gap 5 is followed by *members will find that this test*, which requires a test. Gap 1 is followed by a sentence beginning *A summary that gives each document a paragraph*, which requires the fault to have been named as organisational. Gap 4 is followed by *the second is*, which requires the first to have been completed.**'));
out.push(p('⚠ **E is the distractor and it is the standard build:** **true, relevant, and structurally unattached.** ⚠ **It would sit most plausibly at gap 1, because the paragraph is about long files** — **and the sentence after gap 1 is about organisation and not about counting, so E leaves it stranded.**'));
out.push(p('⚠ **The drill: cover the options, then for each gap write in six words what the missing sentence must do, reading the sentence AFTER the gap first.** ⚠ **Candidates taught to read backwards only will get gaps 2 and 5 wrong**, **because both are completed by what follows rather than by what precedes.**'));
out.push(stage('6', 'Write with help – sample exam answer (47 words)'));
out.push(sample(null, [
  '**To:** Mr Ayoub   **From:** N. Mansour   **Date:** 22 January   **Subject:** The bundle — summary',
  '⚠ **Three of the twenty-two documents decide the claim; nineteen are of no consequence and are listed with a line each.**',
  '⚠ **There is no record anywhere of the telephone call of 14 May, and the absence is ours.**',
  '⚠ **I am asking for twenty minutes with you and Mr Sayegh on Thursday.**',
]));
out.push(p('⚠ **Forty-seven words, three content points, and nothing about the dispute itself** — **which Mr Ayoub has been living with since January.** ⚠ **The counts are fourteen words and the absence is sixteen, of which *the absence is ours* is four** — **and those four are the marks.** ⚠ **And the ask is an ask: twenty minutes, two named people, a named day.**'));
out.push(stage('6P', 'Check together – sample completed checklist'));
out.push(table(['Checklist', '✓ / ✗'], [
  ['Two counts that add up', '**✓** — **3 + 19 = 22**'],
  ['The absence, with *the absence is ours* if it is', '**✓**'],
  ['An ask, stated as an ask', '**✓**'],
  ['No summary of the dispute itself', '**✓**'],
  ['40 to 50 words — count them', '**✓** — **47**'],
], [5, 1]));
out.push(note('Mark Part 1 for the absence and for the absence of a narrative. Candidates will want to explain the claim, and at forty-five words any explanation of a claim crowds out all three content points. The absence is the point with the marks on it and *the absence is ours* is the part that gets dropped — because it is the only clause in the message that costs the writer something, and a candidate under time pressure drops the costly clause first. Say that to a class before the task rather than after it.'));
out.push(stage('7', 'Write freely – sample (236 words)'));
out.push(sample(null, [
  'THE 2024 AUDIT FILE: SUMMARY. 24 January. L. Barakat. Three pages. Page 1.',
  'This summary is written to be acted on without the file. The file is 96 pages and 31 schedules, and every load-bearing sentence below carries a page reference. Four schedules decide the open questions; twenty-seven are correct, relevant and of no consequence, and are listed on page 3 with a line each.',
  'Is there an unprovided liability? One. The Homs site is carried at 2.4 million on an internal estimate made in 2021 and has never been valued by anybody outside this company. [p. 18]',
  'What does the auditor require before signing? A third-party valuation of the Homs site, or a provision. He has required this in each of the last three years and in the same words each time. [pp. 18; 2022 p. 14; 2023 p. 16]',
  'What is the stock position? The count of 28 December ties to the ledger within 0.4 per cent, which is within tolerance and is the largest variance in three years. [pp. 40–44]',
  'What does the file say about the gate sheet? That it is the primary record of what left the yard, and is not a record of condition. [p. 4] The second half of that sentence is quoted nowhere in our own correspondence.',
  'What the file does not contain: a valuation of the Homs site of any date. The absence is ours; it has been requested three times and never obtained.',
]));
out.push(p('⚠ **This is the sample for the end of the unit and the last two lines are why.** ⚠ **The writer has found Mr Attar\'s whole sentence at page four of her own file, a day after the mediation, and noticed that the second half is quoted nowhere in the firm\'s correspondence** — ⚠ **and the absence is named with the four words and with how often it has been asked for.** **Every cycle of the unit is in two hundred and thirty-six words.**'));

// ===================== UNIT CHECK =====================
out.push(pb());
out.push(stage('✓', 'Unit 17 check'));
out.push(p('**A  Language — the answers.**'));
out.push(table(['**Q**', '1', '2', '3', '4', '5', '6', '7', '8'], [['Answer', 'b', 'c', 'b', 'c', 'a', 'b', 'a', 'a']], [1.2, 0.6, 0.6, 0.6, 0.6, 0.6, 0.6, 0.6, 0.6]));
out.push(p('⚠ **Q1 is the bare infinitive after *to*** — *written to be acted on* — **and *being acted on* is the error to expect from learners who have met the passive gerund.** ⚠ **Q4 is *on either side*, which is the idiom; *at* and *in* are both wrong and *on* is not deducible.** ⚠ **Q6 is *relied on*, and the preposition travels with the participle** — *the document relied on*, **not *relied at*.** ⚠ **Q8 is the present perfect for a state continuing to now** — *nobody has read page four* — **and *is reading* would make it a present action, which is the opposite of the point.**'));
out.push(p('**B  Listening (Track 17.15).**   **The quotation as the firm uses it:** ⚠ *the gate sheet is the primary record.*   **The sentence in place:** ⚠ *the gate sheet is the primary record of what left the yard, and is not a record of condition.*   **The half left off, and whose it is:** ⚠ **the second half** — **and it is the half he wrote the sentence for.**   **Where the short form has travelled:** ⚠ **three of the firm\'s own letters and the facility paper sent to the bank in June** — **and the claimant is now quoting the firm\'s quotation of him.**   **Why he will not write a letter:** ⚠ **it would make him a witness in a dispute about a company he audits, and that is worth less to the firm than the note is.**   **What the remedy is:** ⚠ **that somebody reads page four** — **the note is in the bundle in full at page 177 and has always said what it says.**'));
out.push(p('**C  Reading.**  ⚠ **Organised by question** — *what is claimed · was it known · was it disclosed · what does the agreement require*. ⚠ **Three of the twenty-two decide it.** ⚠ **The most important line is about the absence of any record of the call of 14 May, because a summary that lists what a bundle contains and not what it lacks tells the reader the bundle is complete** — **and the one thing the firm knows is that it is not.** **Give the marks for *tells the reader it is complete*; do not give them for *because it is our best point*.**'));
out.push(p('**D  Writing – sample (102 words).**'));
out.push(sample(null, [
  '⚠ **The hospital arrangement runs to 24 pages and 9 schedules. Two schedules decide every question that has arisen; seven are correct, relevant and of no consequence.**',
  '⚠ **What rate applies to benches? 2,150 under schedule 2, which neither side has amended since 2023. [sch. 2, p. 11]**',
  '⚠ **What the arrangement does not contain: any provision for a price review of any kind.** ⚠ **The absence is both sides\' and it is the reason the rate question cannot be settled by reading it.**',
]));
out.push(box('Marking the unit check', [
  '**A  Language — 8 marks**, one each.',
  '**B  Listening — 6 marks**, one for each gap. ⚠ **Give the fifth mark only for both halves** — **that a letter would make him a witness AND that his independence is worth more to the firm than his explanation.** **The second half is the part that makes his refusal a service rather than an inconvenience.**',
  '**C  Reading — 5 marks:** organised by question (1) · the four questions (1) · three of twenty-two (1) · ⚠ **the absence, and *tells the reader the bundle is complete* (2)** — **and no mark for *because it is our best point*.**',
  '**D  Writing — 6 marks:** two counts that add up (2) · ⚠ **one question-and-answer with a reference inside the answer (2)** · ⚠ **an absence sentence, with whose it is (2).**',
  '**Total 25.** ⚠ **The profile to expect: A split, B high, C split, D split.** **A loses Q4 and Q6, both prepositions that cannot be worked out.** ⚠ **C loses the absence question, where learners give the firm\'s advantage as the reason rather than the reader\'s false impression of completeness.** ⚠ **And D loses *whose it is* in about half of papers**, **which is the same four words that go missing in the Part 1 task.**',
], C.lteal, C.navy));
out.push(note('Teacher\'s note. Four faults to watch, and the remedy for each. First, the index that looks like a summary. The quickest demonstration is to ask for a question and make the learner find the answer in their own document; when it turns out to be in two non-adjacent paragraphs, the diagnosis makes itself. Keep the index — it is the working document the summary is built from — and then write the summary, organised by question. And repeat the real test rather than the accuracy one: would a decision taken on this alone be the same decision? Second, equal proportions. Learners give everything a paragraph because every part of the file is correct and relevant, and the missing word is consequence. Teach the test — if this did not exist, would the answer change — and insist on both counts adding to the total. Then make them list the ones that do not matter, with page numbers, because a document left out has been judged in private and one on a one-line list has been judged where somebody can disagree. Third, the half-quotation, and this is the fault with the longest reach. The rule is that a quotation which improves your side is one you have not finished reading, and the test is whether the other side would quote it the same way. Make them apply it to their own documents FIRST, because those are the only quotations their side can be caught shortening and they are the ones nobody suspects. Expect at least one learner to discover a cut made inside their own firm years ago by somebody choosing what would fit on a form. Fourth, and this one cannot be taught without a second person: the sentence that refers to a document instead of saying what it says. Pair them, have one read with the original shut, and collect what fails. The writer cannot do this alone, because they know what the referred-to document says, and the four sentences that fail will look fine to them. Teach misreadability as a separate question from consequence while you are there: a document of no consequence can need a sentence on page one, and that is the one case the proportion rule gets exactly wrong. Two notes on 17.7. Mr Attar does four things and no more — asks for the document, names the omission, declines the letter, gives the remedy — and the economy of it is the lesson. And his refusal is a service and not an obstruction: a letter explaining his own sentence would make him a witness in a dispute about a company he audits, and the firm needs his independence more than it needs his explanation. Learners miss that entirely on first reading and it is worth five minutes.'));

if (require.main === module) L.build(out, process.argv[2], 'Proactive Business English B2 · Book 2 · Syria Edition · Unit 17 · Answer Key');
module.exports = out;
